  sub(AR("बिस्मिल्ला खाँ बालाजी के मंदिर में शहनाई बजाते थे।", "वे धर्म के संकीर्ण बंधनों से ऊपर उठकर संगीत को पूजा मानते थे।", 2), 1),
  sub(M("‘सुर साधना से ही आता है’ — इस कथन में कौन-सा जीवन-मूल्य प्रकट होता है?", ["निरंतर अभ्यास और साधना का महत्त्व", "भाग्य पर भरोसा", "दिखावा", "आलस्य"], 0), 1),
